"""LlamaIndex integration — StrataMemoryStore.

Install: pip install strata-memory[llamaindex]
"""

from __future__ import annotations

from typing import Any

from strata.client import StrataClient


class StrataMemoryStore:
    """LlamaIndex-compatible memory store backed by Strata.

    Provides put/get/query methods following LlamaIndex memory patterns.

    Usage::

        from strata import StrataClient
        from strata.integrations.llamaindex import StrataMemoryStore

        s = StrataClient()
        store = StrataMemoryStore(client=s, project="my-index")

        store.put("React Server Components handle data fetching server-side")
        results = store.query("data fetching patterns")
    """

    def __init__(
        self,
        client: StrataClient,
        *,
        project: str | None = None,
        user: str | None = None,
    ) -> None:
        self._client = client
        self._project = project
        self._user = user

    def put(
        self,
        text: str,
        *,
        type: str = "learning",
        tags: list[str] | None = None,
    ) -> str:
        """Store a memory. Returns the memory ID."""
        mem = self._client.add(
            text,
            type=type,
            tags=tags,
            project=self._project,
            user=self._user,
        )
        return mem.id

    def query(
        self,
        query: str,
        *,
        limit: int = 10,
    ) -> list[dict[str, Any]]:
        """Query the memory store. Returns list of result dicts."""
        results = self._client.search(
            query,
            limit=limit,
            project=self._project,
            user=self._user,
        )
        return [
            {
                "text": r.text,
                "score": r.score,
                "metadata": {
                    "project": r.project or "",
                    "date": r.date or "",
                },
            }
            for r in results
        ]

    def delete(self, id: str) -> bool:
        """Delete a memory by ID."""
        return self._client.delete(id)
